            try ProtocolConstants(
                protocolVersion: FfiConverterUInt32.read(from: &buf), 
                closeDeviceRevoked: FfiConverterUInt16.read(from: &buf), 
                closeNotAllowed: FfiConverterUInt16.read(from: &buf), 
                closeHostOffline: FfiConverterUInt16.read(from: &buf), 
                errorCapabilityDenied: FfiConverterInt64.read(from: &buf), 
                errorUpdateRequired: FfiConverterInt64.read(from: &buf), 
                errorNotFound: FfiConverterInt64.read(from: &buf), 
                errorInvalidState: FfiConverterInt64.read(from: &buf), 
                errorUnavailable: FfiConverterInt64.read(from: &buf)
        )
    }

    public static func write(_ value: ProtocolConstants, into buf: inout [UInt8]) {
        FfiConverterUInt32.write(value.protocolVersion, into: &buf)
        FfiConverterUInt16.write(value.closeDeviceRevoked, into: &buf)
        FfiConverterUInt16.write(value.closeNotAllowed, into: &buf)
        FfiConverterUInt16.write(value.closeHostOffline, into: &buf)
        FfiConverterInt64.write(value.errorCapabilityDenied, into: &buf)
        FfiConverterInt64.write(value.errorUpdateRequired, into: &buf)
        FfiConverterInt64.write(value.errorNotFound, into: &buf)
        FfiConverterInt64.write(value.errorInvalidState, into: &buf)
        FfiConverterInt64.write(value.errorUnavailable, into: &buf)
    }
}


