/**
 * Every failure the API reports.
 */
public 
enum AgentHostError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The host answered a request with a JSON-RPC error. `code` is one of the
     * codes in [`ProtocolConstants`] (for example capability denied or update
     * required) or a standard JSON-RPC code. `data_json` is the error's
     * `data` member as JSON text, when present.
     */
    case Rpc(code: Int64, detail: String, dataJson: String?
    )
    /**
     * The relay or host closed the connection with a WebSocket close code
     * (4401 revoked, 4403 not allowed, 4404 host offline, …).
     */
    case Closed(code: UInt16, reason: String
    )
    /**
     * Pairing did not complete (refused on the desktop, timed out, …).
     */
    case Pairing(detail: String
    )
    /**
     * An argument was malformed (bad QR payload, bad credentials, bad JSON).
     */
    case InvalidInput(detail: String
    )
    /**
     * Network or tunnel failure without a close code.
     */
    case Transport(detail: String
    )
    /**
     * The client was disconnected; connect again.
     */
    case NotConnected

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension AgentHostError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAgentHostError: FfiConverterRustBuffer {
    typealias SwiftType = AgentHostError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AgentHostError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Rpc(
            code: try FfiConverterInt64.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf), 
            dataJson: try FfiConverterOptionString.read(from: &buf)
            )
        case 2: return .Closed(
            code: try FfiConverterUInt16.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Pairing(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .InvalidInput(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Transport(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 6: return .NotConnected

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AgentHostError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Rpc(code,detail,dataJson):
            writeInt(&buf, Int32(1))
            FfiConverterInt64.write(code, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            FfiConverterOptionString.write(dataJson, into: &buf)
            
        
        case let .Closed(code,reason):
            writeInt(&buf, Int32(2))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Pairing(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .InvalidInput(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Transport(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .NotConnected:
            writeInt(&buf, Int32(6))
        
        }
    }
}


