private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_agenthost_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_agenthost_ffi_checksum_func_pair() != 19282) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agenthost_ffi_checksum_func_parse_pairing_qr() != 15244) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agenthost_ffi_checksum_func_protocol_constants() != 59933) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agenthost_ffi_checksum_method_connectionlistener_on_notification() != 54623) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agenthost_ffi_checksum_method_connectionlistener_on_closed() != 26869) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agenthost_ffi_checksum_method_pairinglistener_on_short_code() != 15567) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agenthost_ffi_checksum_method_remoteclient_call() != 63740) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agenthost_ffi_checksum_method_remoteclient_disconnect() != 17332) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agenthost_ffi_checksum_method_remoteclient_hello() != 35780) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agenthost_ffi_checksum_method_remoteclient_is_connected() != 54864) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_agenthost_ffi_checksum_constructor_remoteclient_connect() != 45504) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiCallbackInitConnectionListener()
    uniffiCallbackInitPairingListener()
    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureAgenthostFfiInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

